solutionCss:
.app-container {
  display: flex;
  height: 100vh;
}

.sidebar {
  background: #1e293b;
  color: white;
  padding: 20px;
  width: 250px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.main-content {
  padding: 30px;
  flex-grow: 1;
}

.stats-grid {
  gap: 20px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

.user-profile {
  gap: 15px;
  display: flex;
  align-items: center;
}

.badge {
  position: absolute;
  top: -5px;
  right: -5px;
  background-color: #ef4444;
  color: white;
  border-radius: 50%;
  width: 18px;
  height: 18px;
  font-size: 12px;
  display: flex;
  justify-content: center;
  align-items: center;
}
